from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self._spy = self.AddEquity("SPY", Resolution.Minute, Market.USA).Symbol
        self.Securities[self._spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self._option_symbol = self.AddOption("SPY", Resolution.Minute, Market.USA).Symbol
        self.Securities[self._option_symbol].SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(
                timedelta(days=0), timedelta(days=365)
            )
        )

        self._fast = SimpleMovingAverage(5)
        self._slow = SimpleMovingAverage(20)
        self._previous_fast = None
        self._previous_slow = None
        self._pending_signal_time = None

        self._held_symbol = None
        self._held_expiry = None
        self._entry_price = None
        self._entry_order_id = None
        self._exit_order_id = None
        self._blocked_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self._spy, consolidator)

    def OnData(self, slice):
        self._liquidate_unexpected_spy_position()
        self._handle_expiration(slice)
        self._evaluate_exit(slice)
        self._evaluate_pending_entry(slice)

    def _on_five_minute_bar(self, sender, bar):
        self._fast.Update(bar.EndTime, bar.Close)
        self._slow.Update(bar.EndTime, bar.Close)

        if self._fast.IsReady and self._slow.IsReady:
            current_fast = self._fast.Current.Value
            current_slow = self._slow.Current.Value

            if (self._previous_fast is not None and
                    self._previous_fast <= self._previous_slow and
                    current_fast > current_slow):
                self._pending_signal_time = bar.EndTime

            self._previous_fast = current_fast
            self._previous_slow = current_slow

    def _evaluate_pending_entry(self, slice):
        if self._pending_signal_time != self.Time:
            return

        self._pending_signal_time = None

        if self._blocked_entry_date == self.Time.date():
            return

        if self._held_symbol is not None or self._entry_order_id is not None:
            return

        if not (self.Time.hour > 9 or (self.Time.hour == 9 and self.Time.minute >= 45)):
            return
        if not (self.Time.hour < 14 or (self.Time.hour == 14 and self.Time.minute <= 30)):
            return

        chain = self._get_option_chain(slice)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain")
            return

        current_date = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: skipped entry; no expiry at least 7 calendar days away")
            return

        expiry = eligible_expiries[0]
        spot = self.Securities[self._spy].Price
        minimum_strike = spot * 1.01

        candidates = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call")
            return

        selected = sorted(candidates, key=lambda c: (c.Strike, str(c.Symbol)))[0]
        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self.Debug(
            f"{self.Time}: submitted entry for {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}"
        )

    def _evaluate_exit(self, slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self._exit_order_id is not None:
            return

        if self._is_pre_expiration_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        contract = self._get_contract_from_slice(slice, self._held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _handle_expiration(self, slice):
        if self._held_symbol is None or self._held_expiry is None:
            return

        if self.Time.date() >= self._held_expiry:
            self._blocked_entry_date = self.Time.date()
            if self._exit_order_id is None:
                self._submit_exit("expiration protection")

    def _is_pre_expiration_time_stop(self):
        if self._held_expiry is None:
            return False

        if self.Time.hour != 15 or self.Time.minute != 45:
            return False

        exchange_hours = self.Securities[self._spy].Exchange.Hours
        previous_trading_day = exchange_hours.GetPreviousTradingDay(self._held_expiry)
        return self.Time.date() == previous_trading_day.date()

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_order_id is not None:
            return

        for order in self.Transactions.GetOpenOrders(self._held_symbol):
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self._held_symbol, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: submitted exit for {self._held_symbol}; {reason}")

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self._spy].Quantity
        if quantity == 0:
            return

        if not self.Transactions.GetOpenOrders(self._spy):
            self.MarketOrder(self._spy, -quantity)
            self.Debug(f"{self.Time}: unexpected SPY exercise/assignment position; liquidating")

    def _get_option_chain(self, slice):
        if self._option_symbol in slice.OptionChains:
            return slice.OptionChains[self._option_symbol]

        for chain in slice.OptionChains.Values:
            if chain.Underlying is not None and chain.Underlying.Symbol == self._spy:
                return chain

        return None

    def _get_contract_from_slice(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            if symbol in chain.Contracts:
                return chain.Contracts[symbol]
        return None

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._held_expiry = order_event.Symbol.ID.Date.date()
                self._entry_price = float(order_event.FillPrice)
                self._entry_order_id = None
                self.Debug(
                    f"{self.Time}: entry filled {self._held_symbol} "
                    f"at {self._entry_price}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: exit filled {order_event.Symbol}")
                self._held_symbol = None
                self._held_expiry = None
                self._entry_price = None
                self._exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._exit_order_id = None

