        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.CancelOpenExitOrders()
            quantity = self.Portfolio[self.held_contract].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
                self.Debug(f"{self.Time}: submitted profit-target exit for {self.held_contract}.")

    def HandleExpirationRisk(self):
        if not self.HasOptionPosition() or self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.CancelOpenExitOrders()
            quantity = self.Portfolio[self.held_contract].Quantity
            if quantity != 0 and not self.IsExitOrderOpen():
                self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
                self.Debug(f"{self.Time}: submitted expiration-protection exit for {self.held_contract}.")
            return

