            return

        next_open = self.Securities[self.spy].Exchange.Hours.GetNextMarketOpen(self.Time, False)
        if next_open.date() == expiry_date:
            self.CancelOpenExitOrders()
            quantity = self.Portfolio[self.held_contract].Quantity
            if quantity != 0 and not self.IsExitOrderOpen():
                self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
                self.Debug(f"{self.Time}: submitted pre-expiration exit for {self.held_contract}.")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if any(order.Symbol == self.spy for order in self.Transactions.GetOpenOrders()):
            return

        self.Debug(f"{self.Time}: unexpected SPY exercise/assignment position; liquidating.")
        self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: entry filled for {order_event.Symbol} at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"{self.Time}: entry order for {order_event.Symbol} did not fill.")
                self.held_contract = None
                self.entry_ticket = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: exit filled for {order_event.Symbol} at {order_event.FillPrice:.2f}.")
                self.held_contract = None
                self.entry_ticket = None
                self.exit_ticket = None
                self.entry_price = None

    def HasOptionPosition(self):
        return self.held_contract is not None and self.Portfolio[self.held_contract].Quantity != 0

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False
        return self.exit_ticket.Status not in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ]

    def CancelOpenExitOrders(self):
        if self.held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if self.entry_ticket is None or order.Id != self.entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

