from AlgorithmImports import *
from datetime import timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity("SPY", Resolution.MINUTE).symbol
        self.securities[self.spy].set_data_normalization_mode(DataNormalizationMode.RAW)

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(lambda universe: universe.include_weeklys().strikes(-100, 100).expiration(0, 365))
        self.option_symbol = option.symbol

        self.closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry = False

        self.held_symbol = None
        self.entry_fill_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.block_entries_on = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self.on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def on_five_minute_bar(self, sender, bar):
        self.closes.add(bar.close)

        if not self.closes.is_ready:
            return

        values = [self.closes[i] for i in range(20)]
        fast = sum(values[:5]) / 5.0
        slow = sum(values[:20]) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end = bar.end_time
        eligible_time = (
            (end.hour > 9 or (end.hour == 9 and end.minute >= 45))
            and (end.hour < 14 or (end.hour == 14 and end.minute <= 30))
        )

        if bullish_cross and eligible_time:
            self.pending_entry = True

    def on_data(self, data):
        self.handle_unexpected_spy_position()
        self.handle_expiration_safety()

        if self.held_symbol is not None and self.portfolio[self.held_symbol].quantity != 0:
            self.handle_option_exit(data)

        if self.pending_entry:
            self.pending_entry = False
            self.try_enter(data)

    def try_enter(self, data):
        if self.block_entries_on == self.time.date():
            return

        if self.held_symbol is not None and self.portfolio[self.held_symbol].quantity != 0:
            return

        if self.entry_order_is_open():
            return

        if self.spy not in data.bars:
            self.debug("Skipped option selection: SPY has no current-minute bar.")
            return

        spy_price = data.bars[self.spy].close
        if spy_price <= 0:
            self.debug("Skipped option selection: invalid SPY price.")
            return

        target_expiry_date = self.time.date() + timedelta(days=7)
        candidates = []

        for chain in data.option_chains.values():
            for contract in chain.contracts.values():
                if contract.right != OptionRight.CALL:
                    continue
                if contract.expiry.date() < target_expiry_date:
                    continue
                candidates.append(contract)

        if not candidates:
            self.debug("Skipped option selection: no eligible call expiration in current Slice.")
            return

        expiry = min(contract.expiry.date() for contract in candidates)
        strike_floor = spy_price * 1.01

        contracts = [
            contract for contract in candidates
            if contract.expiry.date() == expiry and contract.strike >= strike_floor
        ]

        if not contracts:
            self.debug("Skipped option selection: no call strike at least 1% OTM.")
            return

        selected = min(contracts, key=lambda contract: (contract.strike, str(contract.symbol)))
        self.entry_ticket = self.market_order(selected.symbol, 1)
        self.debug(f"Entry submitted: {selected.symbol} exp {expiry} strike {selected.strike}.")

    def handle_option_exit(self, data):
        if self.exit_order_is_open() or self.entry_fill_price is None:
            return

        contract = None
        for chain in data.option_chains.values():
            if self.held_symbol in chain.contracts:
                contract = chain.contracts[self.held_symbol]
                break

