from collections import deque
from datetime import timedelta


class FiveMinuteSpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(-100, 100, timedelta(0), timedelta(days=365))
        self.option_symbol = self.option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_minutes = {}
        self.pending_entry = False

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.expiry_date = None
        self.time_stop_date = None
        self.blocked_entry_dates = set()
        self.spy_liquidation_order_id = None

    def OnData(self, data: Slice):
        today = self.Time.date()

        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationRisk(today)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is not None:
            self.UpdateFiveMinuteBars(spy_bar)

        if self.pending_entry:
            self.pending_entry = False
            self.TryEnter(data)

        self.EvaluateExit(data)

    def UpdateFiveMinuteBars(self, bar: TradeBar):
        bar_time = bar.Time
        if not (bar_time.hour > 9 or (bar_time.hour == 9 and bar_time.minute >= 30)):
            return
        if bar_time.hour >= 16:
            return

        minute_of_day = bar_time.hour * 60 + bar_time.minute
        bucket_minute = minute_of_day - ((minute_of_day - 570) % 5)
        bucket_start = bar_time.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60,
            second=0,
            microsecond=0
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self.FinalizeFiveMinuteBucket()
            self.bucket_start = bucket_start
            self.bucket_minutes = {}

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        self.bucket_minutes[bar_time] = bar

    def FinalizeFiveMinuteBucket(self):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]
        if not all(time in self.bucket_minutes for time in expected_times):
            return

        completed_bar_end = self.bucket_start + timedelta(minutes=5)
        close = self.bucket_minutes[expected_times[-1]].Close
        self.closes.append(close)

        if len(self.closes) < 20:
            return

        values = list(self.closes)
        fast = sum(values[-5:]) / 5.0
        slow = sum(values[-20:]) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish and (
            (completed_bar_end.hour == 9 and completed_bar_end.minute >= 45)
            or 10 <= completed_bar_end.hour <= 13
            or (completed_bar_end.hour == 14 and completed_bar_end.minute <= 30)
        ):
            self.pending_entry = True

    def TryEnter(self, data: Slice):
        today = self.Time.date()
        if today in self.blocked_entry_dates:
            return
        if self.entry_order_id is not None or self.exit_order_id is not None:
            return
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity != 0:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain")
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Entry skipped: no current SPY price")
            return

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= today + timedelta(days=7)
        })
        if not eligible_expiries:
            self.Debug("Entry skipped: no expiry at least 7 calendar days out")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = spy_bar.Close * 1.01
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def EvaluateExit(self, data: Slice):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if (
            self.time_stop_date is not None
            and self.Time.date() == self.time_stop_date
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.SubmitExit("time stop")
            return

        if self.entry_fill_price is None or self.exit_order_id is not None:
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.CancelOtherOpenExitOrders()
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_symbol}")

    def CancelOtherOpenExitOrders(self):
        if self.held_symbol is None:
            return

        for order in self.Transactions.GetOpenOrders(self.held_symbol):
            if self.entry_order_id is None or order.Id != self.entry_order_id:
                self.Transactions.CancelOrder(order.Id)

    def HandleExpirationRisk(self, today):
        if self.held_symbol is not None and self.expiry_date is not None and today >= self.expiry_date:
            self.blocked_entry_dates.add(today)
            self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        self.spy_liquidation_order_id = ticket.OrderId
        self.Debug("Unexpected SPY exercise/assignment position: liquidation submitted")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.PartiallyFilled:
                self.held_symbol = order_event.Symbol

            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.expiry_date = order_event.Symbol.ID.Date.date()
                self.time_stop_date = self.PreviousTradingDay(self.expiry_date)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} @ {self.entry_fill_price:.2f}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} @ {order_event.FillPrice:.2f}")
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_fill_price = None
                self.expiry_date = None
                self.time_stop_date = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

        if order_event.OrderId == self.spy_liquidation_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.spy_liquidation_order_id = None

