from AlgorithmImports import *
from datetime import timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(0), timedelta(days=90))
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

        self.held_contract = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.no_entry_today = False

    def OnFiveMinuteBar(self, sender, bar):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        if self.held_contract is not None or self.HasOpenEntryOrder() or self.no_entry_today:
            return

        bar_end = bar.EndTime
        if (bar_end.hour, bar_end.minute) < (9, 45) or (bar_end.hour, bar_end.minute) > (14, 30):
            return

        if previous_fast <= previous_slow and self.fast.Current.Value > self.slow.Current.Value:
            self.TryEnter()

    def TryEnter(self):
        chain = self.CurrentSlice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped: no option chain.")
            return

        spy_price = self.Securities[self.spy_symbol].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        min_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({contract.Expiry.date() for contract in chain
                           if contract.Right == OptionRight.Call and contract.Expiry.date() >= min_expiry})

        if not expiries:
            self.Debug(f"{self.Time}: Entry skipped: no qualifying expiration.")
            return

        expiry = expiries[0]
        minimum_strike = 1.01 * spy_price
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped: no qualifying call strike.")
            return

        selected = min(candidates, key=lambda x: (x.Strike, str(x.Symbol)))
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(f"{self.Time}: Entry submitted: {selected.Symbol}.")

    def OnData(self, slice):
        if self.Time.date() != getattr(self, "_last_date", None):
            self._last_date = self.Time.date()
            self.no_entry_today = False

        if self.Portfolio[self.spy_symbol].Invested and self.held_contract is None:
            self.Liquidate(self.spy_symbol)
            self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment position liquidated.")

        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.no_entry_today = True
            self.SubmitExit("expiration processing")
            return

        if self.Time.date() == expiry_date - timedelta(days=1) and self.Time.hour == 15 and self.Time.minute == 45:
            self.SubmitExit("pre-expiration time stop")
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        ):
            return

        quote = slice.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None or self.entry_price is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        if (bid + ask) / 2.0 >= 1.5 * self.entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        ):
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id)

        quantity = -self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_contract, quantity)
            self.Debug(f"{self.Time}: Exit submitted ({reason}): {self.held_contract}.")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None
                self.Debug(f"{self.Time}: Entry filled: {order_event.Symbol} at {order_event.FillPrice}.")
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled: {order_event.Symbol} at {order_event.FillPrice}.")
                self.held_contract = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

    def HasOpenEntryOrder(self):
        return self.entry_ticket is not None and self.entry_ticket.Status not in (
            OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid
        )

